import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/Books/02-SupplementaryArticles/Thinking/05-All-artificial-intelligence-turns-out-to-be-very-weak.html","title":"05-机器能叛变吗？别怕，它们还太弱了！","lang":"zh-CN","frontmatter":{"title":"05-机器能叛变吗？别怕，它们还太弱了！","icon":"read","date":"2025-04-26T14:39:50.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":false,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"watermark":{"width":200,"height":200,"content":"《编程启蒙：思维与代码》作者：黄家宝","opacity":0.5},"description":"还记得我们之前在《如何识破伪装成人类的机器人？从图灵测试谈起》提到的《机械姬》吗？里面的机器人艾娃杀了自己的创造者，逃出实验室，开启了自由人生。 其实，机器人叛变这种桥段，在科幻作品里屡见不鲜。比如，在《复仇者联盟》中，人工智能奥创也试图消灭人类，重新塑造世界。 听到这里，人类是不是该小紧张一下？现实中，人工智能越来越聪明了，难道它们真的有一天会反抗我...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"05-机器能叛变吗？别怕，它们还太弱了！\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2025-04-26T14:39:50.000Z\\",\\"dateModified\\":\\"2025-05-07T11:44:53.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/Books/02-SupplementaryArticles/Thinking/05-All-artificial-intelligence-turns-out-to-be-very-weak.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"05-机器能叛变吗？别怕，它们还太弱了！"}],["meta",{"property":"og:description","content":"还记得我们之前在《如何识破伪装成人类的机器人？从图灵测试谈起》提到的《机械姬》吗？里面的机器人艾娃杀了自己的创造者，逃出实验室，开启了自由人生。 其实，机器人叛变这种桥段，在科幻作品里屡见不鲜。比如，在《复仇者联盟》中，人工智能奥创也试图消灭人类，重新塑造世界。 听到这里，人类是不是该小紧张一下？现实中，人工智能越来越聪明了，难道它们真的有一天会反抗我..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-05-07T11:44:53.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:published_time","content":"2025-04-26T14:39:50.000Z"}],["meta",{"property":"article:modified_time","content":"2025-05-07T11:44:53.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1746618293000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":12,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"74434ca22b4dbb049c5d8cf6d6a63a10b07fd700","time":1746618293000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新侧边栏，添加目录项并禁用各章节的导航栏"},{"hash":"9c9b2ba2b8ef4cc1b61c10448101aa350e9450ee","time":1746617928000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"feat: 更新思维章节，添加水印信息并调整侧边栏内容"},{"hash":"9fe778ec384b68cfc405b291cf05475dbfed5c84","time":1746616663000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新"},{"hash":"32742c5a7b4409f9d8343e4a7f4a392536d11f6a","time":1746616274000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新思维补充文章"},{"hash":"0b4e3a9a7ab071d34735c47f30236cc1f764e581","time":1745655145000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"388e0d8d2559e8c7603556b0a6d0d0f59f7f3f5e","time":1745654647000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"7ee8148f3d6039bc2c0ca6118f9ea140ab57ab4e","time":1745650202000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新侧边栏和文章标题，添加新内容以增强可读性和结构"},{"hash":"5e09f72a9f3d0e1c6b3071fd84c3809c76136d7e","time":1745649742000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"a2bcd18dbd6b8b3cefb8b96f0ab4ad5e3ac5f65d","time":1745649547000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft for \\"All artificial intelligence turns out to be very weak\\" article"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.22,"words":2465},"filePathRelative":"Books/02-SupplementaryArticles/Thinking/05-All-artificial-intelligence-turns-out-to-be-very-weak.md","excerpt":"<figure><figcaption></figcaption></figure>\\n<p>还记得我们之前在《如何识破伪装成人类的机器人？从图灵测试谈起》提到的<strong>《机械姬》</strong>吗？里面的机器人<strong>艾娃</strong>杀了自己的创造者，逃出实验室，开启了自由人生。</p>\\n<p>其实，机器人叛变这种桥段，在科幻作品里屡见不鲜。比如，在<strong>《复仇者联盟》</strong>中，人工智能<strong>奥创</strong>也试图消灭人类，重新塑造世界。</p>\\n<p>听到这里，人类是不是该小紧张一下？现实中，人工智能越来越聪明了，难道它们真的有一天会反抗我们？</p>","autoDesc":true}`),a={name:`05-All-artificial-intelligence-turns-out-to-be-very-weak.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/image-20250426151241082-D1BBD965.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>还记得我们之前在《如何识破伪装成人类的机器人？从图灵测试谈起》提到的<strong>《机械姬》</strong>吗？里面的机器人<strong>艾娃</strong>杀了自己的创造者，逃出实验室，开启了自由人生。</p><p>其实，机器人叛变这种桥段，在科幻作品里屡见不鲜。比如，在<strong>《复仇者联盟》</strong>中，人工智能<strong>奥创</strong>也试图消灭人类，重新塑造世界。</p><p>听到这里，人类是不是该小紧张一下？现实中，人工智能越来越聪明了，难道它们真的有一天会反抗我们？</p><p>别慌！科学家们早就把这事儿放在了心上，还认真研究过。</p><p>比如，加州大学洛杉矶分校（UCLA）的研究者们，把现有的人工智能分成了两大类：一种叫<strong>鹦鹉型智能</strong>，另一种叫<strong>乌鸦型智能</strong>。</p><h2 id="_1-鹦鹉和乌鸦-两种不同的智慧" tabindex="-1"><a class="header-anchor" href="#_1-鹦鹉和乌鸦-两种不同的智慧"><span>1. 鹦鹉和乌鸦：两种不同的智慧</span></a></h2><figure><img src="/assets/image-20250426151511235-CHNITfpE.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>鹦鹉能学人说话，听起来聪明极了。但其实它们只是<strong>复读机</strong>，对自己说的内容根本没理解。无论你问啥，它可能都是一句标准回答。你问：“今天吃了啥？”它回答：“吃了。”你问：“哥哥去哪了？”它还是：“吃了。”场面有点尴尬。</p><p>乌鸦就不一样了。它们不仅能模仿，还会<strong>独立思考</strong>。</p><p>比如，在日本，有一种乌鸦特别爱吃核桃。但核桃壳太硬，啄不开怎么办？乌鸦们想了个绝招：把核桃扔到马路上，让汽车压碎！</p><p>更厉害的是，它们甚至懂得观察交通信号灯：绿灯时扔核桃，红灯时安全下地捡核桃仁。简直像小小的交通专家。</p><p>所以，乌鸦的智慧，不只是模仿，而是懂得<strong>灵活运用环境</strong>。</p><h2 id="_2-今天的人工智能-只停留在-鹦鹉阶段" tabindex="-1"><a class="header-anchor" href="#_2-今天的人工智能-只停留在-鹦鹉阶段"><span>2. 今天的人工智能：只停留在“鹦鹉阶段”</span></a></h2><p>人工智能专家指出，如今我们身边的 AI，比如 <strong>AlphaGo</strong>、<strong>语音识别助手</strong>、<strong>推荐算法</strong>，其实都是“鹦鹉型智能”。</p><p>它们能执行复杂任务，比如下围棋、识别语音，但只是机械地模仿人类的思考路径，<strong>并不真正理解</strong>自己在做什么。</p><p>更重要的是，这类 AI 的能力<strong>无法迁移</strong>：AlphaGo 会下围棋，但不会写诗；语音助手能听懂指令，却推荐不了新电影。</p><p>所以，这类人工智能又被称为<strong>弱人工智能</strong>。它们的局限性，让人类完全不用担心被取代或威胁。</p><p>哎，到这你有可能会说：现在还有 ChatGPT、DeepSeek 等优秀的大模型吗，你上面的例子顶多算介绍什么是鹦鹉智能，但不能完全代码。并且例子还有些过时，是不是会这么想呢？——你的想法是对的，但是别急，我接下来就要讲到。</p><p>身处 2025 年的你，应该知道：最近几年人工智能世界发生了大地震——各式各样的超级大模型一窝蜂地冒了出来。</p><p>像 OpenAI 家的 <strong>GPT-4o</strong>、Anthropic 家的 <strong>Claude 3</strong>、谷歌家的 <strong>Gemini 1.5</strong>，还有国内的 <strong>DeepSeek</strong>、<strong>通义千问</strong>、<strong>百川</strong>、<strong>月之暗面（Moonshot）</strong>……每一个听起来都像是“未来机器人的大脑原型”。</p><p>这些人工智能能聊天、写作、画画，甚至还能做数学题、编程、视频生成（比如 OpenAI 出的 <strong>Sora</strong>，能让 AI 直接“拍电影”）。</p><p>那么，它们是不是已经超越了鹦鹉型智能，变成真正会思考的“乌鸦型智能”了呢？</p><p>很遗憾，答案还是：<strong>没有</strong>。</p><p>虽然今天的大模型看起来无所不能，实际上，它们的本质依然没有跳出鹦鹉的范畴。也就是说，它们依旧是在海量数据中找规律，在模式匹配里找到最佳回答——就像鹦鹉背诵人类的话一样。只是，这只鹦鹉太聪明了，记得太多了，反应也快得吓人，所以给人一种“好像懂了”的错觉。</p><p>但一旦脱离了它们训练过的数据，它们就会露馅——犯一些让人哭笑不得的低级错误，比如：</p><ul><li>一本正经地编造不存在的资料（这叫“幻觉”问题）；</li><li>无法真正理解问题背后的<strong>因果关系</strong>；</li><li>遇到复杂的新情境时，不知道该如何应对，只能瞎猜。</li></ul><p>所以，不管它们多强大，目前的大模型们，依然只能算是<strong>超级鹦鹉</strong>，还远远不是能独立思考、拥有意识的“乌鸦型智能”。</p><p>换句话说，不管是 GPT、Claude，还是 DeepSeek，它们现在能做的事情，其实跟早期的 AlphaGo、语音助手、小冰这些 AI，是一脉相承的：<strong>更快、更全，但不是更懂。</strong></p><p>真正能思考、能自己发现问题、能灵活适应新世界的“乌鸦型 AI”，还只存在于科幻电影和人类的想象中。</p><p>至少，今天的你，完全不用担心哪天醒来，发现AI真的统治了世界。</p><h2 id="_3-真正值得注意的是-乌鸦型智能" tabindex="-1"><a class="header-anchor" href="#_3-真正值得注意的是-乌鸦型智能"><span>3. 真正值得注意的是“乌鸦型智能”</span></a></h2><p>如果有一天，人工智能不再只是模仿，而能像乌鸦一样独立思考，那就进入了所谓的<strong>强人工智能</strong>阶段。</p><p>比如，《机械姬》中的艾娃就属于这种类型：能自主学习，有自我意识，甚至能制定逃脱计划。这种AI，理论上和人类在智力上没有本质差别，甚至可能超越我们。</p><p>那么——现实中，科学家能不能做出“乌鸦型智能”呢？</p><p>目前，还没有。</p><p>不过，科学家们也想出了一个挺有趣的尝试方法，那就是<strong>让 AI 自己进化</strong>。</p><p>这种方法是通过<strong>模仿生物进化</strong>，让人工智能自己总结经验，学会思考。其中比较成功的一个项目，是让人工智能玩捉迷藏<strong>大战</strong>。</p><h2 id="_4-捉迷藏大战-让-ai-自我成长" tabindex="-1"><a class="header-anchor" href="#_4-捉迷藏大战-让-ai-自我成长"><span>4. 捉迷藏大战：让 AI 自我成长</span></a></h2><figure><img src="/assets/image-20250426160620862-BRByRqP7.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>科学家们设计了一个虚拟世界，里面有两队小人：红队和蓝队。</p><ul><li>红队的任务是抓住蓝队，成功则得1分。</li><li>蓝队的目标是逃脱，成功也能得1分。</li><li>房间里还放着各种道具，比如箱子、木板，小人们可以自由使用。</li></ul><p>每进行一场比赛，AI 们都会记录经验，不断优化策略，就像是动物在进化。</p><p>最开始，小人们只会藏在角落。但经过<strong>数百万次训练</strong>，蓝队学会了用箱子堵门，红队又学会了搭梯子突破。</p><p>后来，环境变复杂了，蓝队甚至能用道具临时搭建小屋，彻底隔离红队！</p><p>这就像一场微缩版的“进化史”：最初的傻乎乎小人，经过千锤百炼后，拥有了越来越高级的生存技能。</p><h2 id="_5-能靠进化-培养出强人工智能吗" tabindex="-1"><a class="header-anchor" href="#_5-能靠进化-培养出强人工智能吗"><span>5. 能靠进化，培养出强人工智能吗？</span></a></h2><p>听起来似乎有希望？</p><p>如果环境足够复杂，小人们会不会学会交流、学习，乃至思考呢？是不是有一天，我们能用这种方法培养出真正的强人工智能？</p><p>理论上不错，但现实非常骨感。</p><p>因为——<strong>人类自己对大脑的运作方式都了解得不够深</strong>。在这种认知水平下，想要让机器模拟出真正的人类智能，简直像是空中楼阁。</p><h2 id="_6-ai-进化的乌龙事件" tabindex="-1"><a class="header-anchor" href="#_6-ai-进化的乌龙事件"><span>6. AI 进化的乌龙事件</span></a></h2><figure><img src="/assets/image-20250426160902565-eS8ZtJtT.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>要想让 AI 自己进化，还真不是一条平坦路。</p><p>有个有趣的例子：一位科学家做了一个“狼捉羊”的模拟游戏，和之前捉迷藏差不多，只不过换成了狼和羊。</p><p>为了让狼更努力地追羊，规则设定是每过一秒，狼如果没捉到羊，就要扣 0.01分，而捉到羊就加 10分。</p><p>结果呢？</p><p>在进行<strong>二十万次试验</strong>后，狼们纷纷放弃治疗——一开局就冲向墙壁，自爆自杀！</p><p>为什么？前边小红人小蓝人都变得那么厉害，怎么轮到狼就只学会自杀了呢？原来，在这个游戏里，<strong>狼实在是太难捉到羊了</strong>，与其等下去每秒钟都要扣分，那还不如一开局就死了算了，扣的分还少一点。</p><p>这就是“进化”的奇妙之处：有时候，不是更聪明，而是学会了“逃避痛苦”。</p><p>所以我们需要知道：在相似的实验中，人工智能的行为完全不一样，有的学会了聪明的策略，有的却崩溃到自杀。要想通过这种方法，获得非常高级的人工智能，真的是很难的一条路。</p><h2 id="_7-小结-现在的-ai-还早着呢" tabindex="-1"><a class="header-anchor" href="#_7-小结-现在的-ai-还早着呢"><span>7. 小结：现在的 AI，还早着呢！</span></a></h2><figure><img src="/assets/image-20250426161153015-CZHsY18p.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>总结一下：</p><ul><li>现阶段的 AI，还是“鹦鹉型智能”，没办法真正自主思考。</li><li>强人工智能（乌鸦型）目前只存在于理论中，距离现实应用还非常遥远。</li><li>未来要想造出真正有意识的机器，生物学、数学、物理、化学各领域都得有重大突破才行。</li></ul><p>所以啊，短时间内，人类完全不用担心机器人造反的剧情会搬到现实世界。更重要的是，说不定未来推动这一切进步的人，就是正在读这本书的你呢！</p>`,66)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};